const (
	TunnelResourceStatusActive   TunnelResourceStatus = "active"
	TunnelResourceStatusDeleting TunnelResourceStatus = "deleting"
)

// AllValues returns all TunnelResourceStatus values.
func (TunnelResourceStatus) AllValues() []TunnelResourceStatus {
	return []TunnelResourceStatus{
		TunnelResourceStatusActive,
		TunnelResourceStatusDeleting,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s TunnelResourceStatus) MarshalText() ([]byte, error) {
	switch s {
	case TunnelResourceStatusActive:
		return []byte(s), nil
	case TunnelResourceStatusDeleting:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *TunnelResourceStatus) UnmarshalText(data []byte) error {
	switch TunnelResourceStatus(data) {
	case TunnelResourceStatusActive:
		*s = TunnelResourceStatusActive
		return nil
	case TunnelResourceStatusDeleting:
		*s = TunnelResourceStatusDeleting
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

